import React, { useEffect, useState } from 'react';
import { backendApi } from '../api/backend';
import CarGrid from '../components/CarGrid';
import { LoadingState, ErrorState } from '../components/admin/AdminStates';

export default function Cars() {
  const [cars, setCars] = useState([]);
  const [search, setSearch] = useState('');
  const [typeFilter, setTypeFilter] = useState('all');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const loadCars = () => {
    setLoading(true);
    setError(null);
    backendApi.getCars()
      .then((data) => setCars(data || []))
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    loadCars();
  }, []);

  const filteredCars = cars.filter((car) => {
    const matchText = `${car.brand} ${car.model}`.toLowerCase().includes(search.toLowerCase());
    const matchType = typeFilter === 'all' || car.car_type === typeFilter;
    return matchText && matchType;
  });

  return (
    <div className="space-y-6">
      <h1 className="text-2xl font-bold">รายการรถเช่าทั้งหมด</h1>

      <div className="flex flex-col md:flex-row gap-4 bg-gray-50 p-4 rounded-lg border">
        <input
          type="text"
          placeholder="ค้นหายี่ห้อ หรือ รุ่นรถ..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className="border p-2 rounded flex-1 bg-white"
        />
        <select
          value={typeFilter}
          onChange={(e) => setTypeFilter(e.target.value)}
          className="border p-2 rounded bg-white"
        >
          <option value="all">ทุกประเภทรถ</option>
          <option value="Sedan">รถเก๋ง (Sedan)</option>
          <option value="SUV">รถอเนกประสงค์ (SUV)</option>
          <option value="Eco">รถประหยัดน้ำมัน (Eco)</option>
        </select>
      </div>

      {loading && <LoadingState />}
      {error && <ErrorState message={error} onRetry={loadCars} />}
      {!loading && !error && <CarGrid cars={filteredCars} />}
    </div>
  );
}
